import { useEffect, useState } from "react";
import { Box } from "@mui/material";
import LandingPage from "../pages/LandingPage";
import CourseDetailsPage from "../pages/CourseDetailsPage";
import masterData from "../data/masterData.json";
import { scrollToTop } from "../components/LenisSmoothScroll";
import type { NavigationState } from "../types/fellowship";

export default function Home() {
  const [nav, setNav] = useState<NavigationState>({ view: "landing" });

  useEffect(() => {
    scrollToTop(true);
  }, [nav.view, nav.programId, nav.specialtyId]);

  const goLanding = () => setNav({ view: "landing" });

  const viewPrograms = (specialtyId: string) => {
    const first = masterData.programs.find((p) => p.specialtyId === specialtyId);
    setNav({ view: "course", specialtyId, programId: first?.id });
  };

  const learnMore = (programId: string) => {
    const program = masterData.programs.find((p) => p.id === programId);
    setNav({
      view: "course",
      programId,
      specialtyId: program?.specialtyId,
    });
  };

  const viewAllPrograms = () => {
    const first = masterData.programs.find((p) => p.featured) || masterData.programs[0];
    setNav({
      view: "course",
      specialtyId: first.specialtyId,
      programId: first.id,
    });
  };

  if (nav.view === "course") {
    return (
      <Box>
        <CourseDetailsPage
          specialtyId={nav.specialtyId}
          programId={nav.programId}
          onBack={goLanding}
          onLearnMore={learnMore}
        />
      </Box>
    );
  }

  return (
    <LandingPage
      onViewPrograms={viewPrograms}
      onLearnMore={learnMore}
      onViewAllPrograms={viewAllPrograms}
    />
  );
}
